class Solution {
 static const int MOD=1000000007;
 long long power(long long a,long long b){long long r=1;while(b){if(b&1)r=r*a%MOD;a=a*a%MOD;b>>=1;}return r;}
public:
 int maxNiceDivisors(int primeFactors){
  if(primeFactors<=3)return primeFactors;
  int q=primeFactors/3,r=primeFactors%3;
  if(r==0)return power(3,q);
  if(r==1)return power(3,q-1)*4%MOD;
  return power(3,q)*2%MOD;
 }
};
